#include <SPI.h>
#include <Adafruit_GFX.h>

// XIAO ESP32S3の物理ピン定義
#define TFT_RST   2   // D1
#define TFT_DC    3   // D2
#define TFT_CS    4   // D3
#define TFT_SCLK  8   // D8
#define TFT_MOSI 10   // D10

// ST7735の内部コマンド定義
#define ST7735_SWRESET 0x01
#define ST7735_SLPOUT  0x11
#define ST7735_FRMCTR1 0xB1
#define ST7735_FRMCTR2 0xB2
#define ST7735_FRMCTR3 0xB3
#define ST7735_INVCTR  0xB4
#define ST7735_PWCTR1  0xC0
#define ST7735_PWCTR2  0xC1
#define ST7735_PWCTR3  0xC2
#define ST7735_PWCTR4  0xC3
#define ST7735_PWCTR5  0xC4
#define ST7735_VMCTR1  0xC5
#define ST7735_INVOFF  0x20
#define ST7735_MADCTL  0x36
#define ST7735_COLMOD  0x3A
#define ST7735_CASET   0x2A
#define ST7735_RASET   0x2B
#define ST7735_RAMWR   0x2C
#define ST7735_DISPON  0x29

// Adafruit_GFXの機能を引き継いで独自のST7735制御クラスを作る
class FixedST7735 : public Adafruit_GFX {
public:
  // 128x160の解像度で設定（横向きで使うため幅160, 高さ128）
  FixedST7735() : Adafruit_GFX(160, 128) {}

  void init() {
    pinMode(TFT_CS, OUTPUT);
    pinMode(TFT_DC, OUTPUT);
    pinMode(TFT_RST, OUTPUT);

    digitalWrite(TFT_CS, HIGH);

    // ESP32S3のSPIを物理ピンで開始 (SPIクロックは安定性を重視して16MHz)
    SPI.begin(TFT_SCLK, -1, TFT_MOSI, TFT_CS);
    SPI.beginTransaction(SPISettings(16000000, MSBFIRST, SPI_MODE0));

    // ハードウェアによる液晶の強制リセット（真っ白対策）
    digitalWrite(TFT_RST, HIGH); delay(10);
    digitalWrite(TFT_RST, LOW);  delay(20);
    digitalWrite(TFT_RST, HIGH); delay(150);

    // 液晶を起動するための必須初期化コマンド群
    sendCmd(ST7735_SWRESET); delay(150);
    sendCmd(ST7735_SLPOUT);  delay(200);

    // フレームレート設定
    sendCmd(ST7735_FRMCTR1); sendData(0x01); sendData(0x2C); sendData(0x2D);

    // カラーモード設定 (16ビットカラー / RGB565)
    sendCmd(ST7735_COLMOD);  sendData(0x05);

    // 画面の向きと色の並び順設定 (一般的なST7735の横向き設定)
    sendCmd(ST7735_MADCTL);  sendData(0xA8); 

    // 表示ON
    sendCmd(ST7735_DISPON);  delay(100);
  }

  // Adafruit_GFXの文字や線を描画するために必須のドット打ち関数
  void drawPixel(int16_t x, int16_t y, uint16_t color) override {
    if ((x < 0) || (x >= _width) || (y < 0) || (y >= _height)) return;
    setAddrWindow(x, y, x, y);
    sendData(color >> 8);
    sendData(color & 0xFF);
  }

  // 高速画面クリア
  void fillScreen(uint16_t color) override {
    setAddrWindow(0, 0, _width - 1, _height - 1);
    digitalWrite(TFT_DC, HIGH);
    digitalWrite(TFT_CS, LOW);
    uint8_t hi = color >> 8, lo = color & 0xFF;
    for (uint32_t i = 0; i < (uint32_t)_width * _height; i++) {
      SPI.transfer(hi);
      SPI.transfer(lo);
    }
    digitalWrite(TFT_CS, HIGH);
  }

private:
  void sendCmd(uint8_t cmd) {
    digitalWrite(TFT_DC, LOW);
    digitalWrite(TFT_CS, LOW);
    SPI.transfer(cmd);
    digitalWrite(TFT_CS, HIGH);
  }

  void sendData(uint8_t data) {
    digitalWrite(TFT_DC, HIGH);
    digitalWrite(TFT_CS, LOW);
    SPI.transfer(data);
    digitalWrite(TFT_CS, HIGH);
  }

  void setAddrWindow(uint8_t x0, uint8_t y0, uint8_t x1, uint8_t y1) {
    sendCmd(ST7735_CASET);
    sendData(0x00); sendData(x0); // 必要に応じてオフセット値を足す箇所
    sendData(0x00); sendData(x1);

    sendCmd(ST7735_RASET);
    sendData(0x00); sendData(y0);
    sendData(0x00); sendData(y1);

    sendCmd(ST7735_RAMWR);
  }
};

// クラスのインスタンス化
FixedST7735 tft;

void setup() {
  Serial.begin(115200);

  // 液晶の初期化
  tft.init();

  // 画面を黒でクリア
  tft.fillScreen(0x0000); // 黒色

  // 文字の描画 (Adafruit_GFXの機能)
  tft.setCursor(10, 20);
  tft.setTextColor(0xFFFF); // 白色
  tft.setTextSize(2);
  tft.println("XIAO ESP32S3");

  tft.setCursor(10, 50);
  tft.setTextColor(0x07E0); // 緑色
  tft.println("DIRECT SPI OK");

  // 外枠の青い長方形を描画
  tft.drawRect(5, 5, 150, 118, 0x001F); // 青色
}

void loop() {
  // 動作確認：文字を交互に書き換える
  tft.setCursor(10, 80);
  tft.setTextColor(0xF800, 0x0000); // 赤（文字背景:黒）
  tft.print("System: RUN ");
  delay(500);

  tft.setCursor(10, 80);
  tft.setTextColor(0xFFE0, 0x0000); // 黄（文字背景:黒）
  tft.print("System: RUN*");
  delay(500);
}
